def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separate groups of nested parentheses from a string into a list of strings.
    Each group is balanced and not nested within each other. Ignore spaces.
    """
    stack = []
    groups = []
    for char in paren_string:
        if char == "(":
            stack.append(char)
        elif char == ")":
            if len(stack) == 0:
                raise ValueError("Unbalanced parentheses")
            stack.pop()
        elif char.isspace():
            continue
        else:
            raise ValueError("Invalid character in parentheses string")
    if len(stack) != 0:
        raise ValueError("Unbalanced parentheses")
    for i in range(len(paren_string)):
        if paren_string[i] == "(":
            j = i + 1
            while j < len(paren_string) and paren_string[j] != ")":
                j += 1
            groups.append(paren_string[i:j+1])
    return groups

